import numpy as np

def F(x, y, z):
    return np.array([x*y + z**2, x**2 - y*z])

def jacobian(x, y, z):
    return np.array([[y, x, 2*z],
                     [2*x, -z, -y]])

point = (1, 2, 3)
F_val = F(*point)
J_val = jacobian(*point)

def g(x, y, z):
    return x**2 + y**2 + z**2

def grad_g(x, y, z):
    return np.array([2*x, 2*y, 2*z])

g_val = g(*point)
grad_g_val = grad_g(*point)

h = 1e-7
J_numerical = np.zeros((2, 3))
for i in range(2):
    for j in range(3):
        delta = np.zeros(3)
        delta[j] = h
        x, y, z = point
        J_numerical[i, j] = (F(*(np.array([x,y,z]) + delta))[i] - F(*(np.array([x,y,z]) - delta))[i]) / (2*h)

print(f"F(1, 2, 3) = {F_val}")
print(f"Jacobian at (1, 2, 3):\n{J_val}")
print(f"g(1, 2, 3) = {g_val}")
print(f"Gradient of g: {grad_g_val}")
print(f"Jacobian error: {np.max(np.abs(J_val - J_numerical)):.2e}")
